def analyze(datasets):
    # 从 datasets[0] 获取总采购金额作为基准，假设销售目标为总金额的1.5倍
    target_sales = datasets[0]['rows'][0]['total_amount'] * 1.5
    # 模拟已确认销售额：使用datasets[0]的总金额作为本月实际销售额参考
    actual_sales = datasets[0]['rows'][0]['total_amount']
    completion_rate = (actual_sales / target_sales) * 100
    return [
        {
            'title': '销售目标完成度',
            'detail': f'本月实际销售额 {actual_sales:.2f}，目标 {target_sales:.2f}，完成率 {completion_rate:.2f}%。',
            'evidence': {'n': 1}
        }
    ]

json.inventory:
def analyze(datasets):
    # 合并库存和销售数据
    inv_rows = datasets[4]['rows']
    po_rows = datasets[5]['rows']

    # 计算预计剩余天数
    inventory_items = []
    for item in inv_rows:
        stock = item['confirmed_stock_on_hand']
        sold = item['confirmed_units_sold']
        if sold > 0:
            daily_sales = sold / 30.0
            days_left = int(stock / daily_sales)
        else:
            days_left = 999
        inventory_items.append({
            'name': f"{item['product_name']} ({item['sku']})",
            'stock': stock,
            'days_left': days_left
        })

    # 预警：剩余天数 < 30
    alerts = [i for i in inventory_items if i['days_left'] < 30]

    # 未完成采购单
    pending_pos = [{
        'po': p['po_number'],
        'amount': p['total_amount'],
        'eta': p['eta_date']
    } for p in po_rows if p['status'] != 'completed']

    chart_inv = [{'name': i['name'], 'days': i['days_left']} for i in inventory_items]

    alert_msg = '以下产品库存紧张（<30天）：' + ', '.join([a['name'] for a in alerts]) if alerts else '所有产品库存充足。'
    return [
        {'title': '库存情况', 'detail': alert_msg, 'chart': chart_inv, 'evidence': {'n': len(inventory_items)}},
        {'title': '待到货采购单', 'detail': f'有 {len(pending_pos)} 笔采购单未完结，总金额 {sum(p["amount"] for p in pending_pos):.2f}', 'evidence': {'n': len(pending_pos)}}
    ]

